from pathlib import Path
import json,hashlib,html,shutil,zipfile
from PIL import Image,ImageDraw,ImageFont
O=Path('outputs/30a_art');old=json.loads(Path('work/30a_art/baseline/30a.json').read_text());new=json.loads(Path('outputs/30a_finish/30a.json').read_text());checks={k:old[k]==new[k] for k in ['districts','lakes','scaleRule']};assert all(checks.values())
raw=Path('outputs/30a_finish/assets/30a-finished.glb').read_bytes();sha=hashlib.sha256(raw).hexdigest();assert sha=='8ef96f1f4e2da746592369f819c2af3231fa7cb4ae5eafdcd94c76cd115a1c52'
assert not any('arcgis' in str(x).lower() or 'esri' in str(x).lower() for x in new['neighborhoodCanopies'].values())
v=json.loads(Path('outputs/30a_finish/verification.json').read_text());e=html.escape
proof={'geometryByteIdentical':True,'glbSha256':sha,'unchangedData':checks,'townCenterErrors':[{k:r[k] for k in ['name','error_m','source']} for r in v['rows'] if r['kind']=='town anchor'],'maxLakeErrorMeters':v['maxActualGlbLakeErrorMeters'],'coldRegionBytes':v['coldRegionBytes'],'canopySource':'OSM plus original procedural illustration. No Esri imagery or imagery-derived masks in current renderer.'};(O/'preservation-checks.json').write_text(json.dumps(proof,indent=2))
font=ImageFont.load_default(size=22);size=Image.open(O/'before/state.png').size;thumbW=590;thumbH=round(size[1]*thumbW/size[0]);rowH=thumbH+50
sheet=Image.new('RGB',(1200,rowH*3),'#f8f0df');draw=ImageDraw.Draw(sheet)
for i,level in enumerate(['state','region','town']):
 for j,phase in enumerate(['before','after']):
  im=Image.open(O/phase/(level+'.png'));assert im.size==size;im.thumbnail((thumbW,thumbH));x=j*600+5;y=i*rowH+38;sheet.paste(im,(x,y));draw.text((x+8,y-29),level.title()+' · '+phase.title(),font=font,fill='#536347')
sheet.save(O/'before-after.jpg',quality=94)
css='body{margin:0;background:#faf2df;color:#4f5f49;font:16px/1.6 system-ui}main{max-width:1400px;padding:36px;margin:auto}h1,h2{font-family:Georgia}h1{font-size:44px}a{color:#ad522a}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}img{width:100%;display:block;border-radius:8px}figure{margin:0}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #ded6bd}section{margin:36px 0}.note{background:#e6ebd1;padding:18px;border-radius:10px}@media(max-width:700px){.pair{grid-template-columns:1fr}main{padding:18px}}'
s=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>30A · illustration restored</title><style>'+css+'</style><main><small>FLORIDA COASTAL · PRESENTATION PASS</small><h1>Illustration over accurate geography</h1><p><a href="../../../explore_coast.html?view=30a&level=region">Open the map</a> · <a href="osm-overlay.png">Town-center overlay</a> · <a href="preservation-checks.json">Preservation checks</a></p><div class="note">The geographic GLB is byte-for-byte unchanged. District positions, lake shapes, price records and the scale rule are unchanged. This pass changes presentation: original illustrated district symbols with leaders, lighter tree groups, stronger architectural color, closer Town framing, white sand and turquoise depth bands.</div><p>Region symbols are deliberately enlarged illustrations, not geographic building footprints. Their leaders end at the actual district coordinates. Town meshes retain their existing footprint and height limits; the camera is closer (850 m instead of 1.25 km) so homes read larger. The 100 m decorative sand band follows the mapped shore on land; it is not a surveyed beach-width claim.</p>']
for level in ['state','region','town']:
 s.append(f'<section><h2>{level.title()} view</h2><div class="pair"><figure><img src="before/{level}.png"><figcaption>Before</figcaption></figure><figure><img src="after/{level}.png"><figcaption>After</figcaption></figure></div></section>')
s.append('<h2>Town-center error overlay</h2><p>Each callout connects to its town center. All anchors are unchanged OSM coordinates: 0.000 m model-to-source displacement. This measures alignment to OSM, not independent ground-truth accuracy. Maximum lake-edge displacement remains 0.603 m.</p><a href="osm-overlay.png"><img src="osm-overlay.png"></a><table><tr><th>Town center</th><th>Error versus OSM</th><th>Source</th></tr>')
for r in proof['townCenterErrors']:s.append(f'<tr><td>{e(r["name"])}</td><td>{r["error_m"]:.3f} m</td><td><a href="{e(r["source"])}">OSM node</a></td></tr>')
s.append('</table><h2>Commercial-use source decision</h2><p>A commercial entitlement for the previous Esri World Imagery use was not established. Esri’s terms distinguish commercial licensing from merely accessing publicly available services. The current map therefore uses replacement canopy masks generated from OSM land/woodland and original procedural garden groves. It no longer requests or renders satellite imagery or imagery-derived canopy masks. The before screenshots are historical local review evidence, not assets for website deployment.</p><p>OpenStreetMap data is available for commercial use under the ODbL, with attribution and applicable share-alike/database obligations. Visible OSM attribution links to its license page. The illustrated map is rendered locally from bundled geometry; it does not depend on the public OSM tile server. OSM tiles appear only in this local QA overlay.</p><p><a href="https://www.openstreetmap.org/copyright">OSM copyright and license</a> · <a href="https://opendatacommons.org/licenses/odbl/1-0/">ODbL terms</a> · <a href="https://www.esri.com/en-us/legal/terms/web-site-service">Esri service terms</a> · <a href="osm-source-data.zip">Underlying OSM source data</a></p><h2>Checks</h2><p>All three zooms rendered with no application console errors observed. Twelve horizontal district labels were checked for overlap in the desktop Region view. The original height cap remains in force. The source GLB remains 3.04 MB; regional page files total '+f'{v["coldRegionBytes"]/1e6:.2f}'+' MB. These local checks do not certify physical-phone load speed or independent height/vegetation surveys.</p><p>© OpenStreetMap contributors. OSM data licensed under ODbL. New district symbols and procedural vegetation are original illustration.</p></main></html>')
(O/'index.html').write_text(''.join(s))
licenseText='OSM source data — © OpenStreetMap contributors\nOpen Database License (ODbL) 1.0: https://opendatacommons.org/licenses/odbl/1-0/\nAttribution and details: https://www.openstreetmap.org/copyright\nSource snapshots retrieved October 16, 2026. Projected geometry derives from those snapshots. No satellite imagery is included.\n'
(O/'LICENSE.txt').write_text(licenseText)
with zipfile.ZipFile(O/'osm-source-data.zip','w',zipfile.ZIP_DEFLATED) as z:
 z.writestr('LICENSE.txt',licenseText)
 for f in ['geometry.json','map-data.json','canopy.json','forest-full.xml','coast-test-coffee.json','water-small.json']:
  z.write(Path('work/30a_finish/source')/f,f)
p=Path('outputs/florida_coastal_atlas/30a-art')
if not p.exists():p.symlink_to(O.resolve(),target_is_directory=True)
print(json.dumps(proof,indent=2))
